select b.master_id categoryId,a.master_id parentId,a.object_code categoryCode,a.object_name categoryName from meicloud_bpmp_material.mt_classification a inner join ( select SUBSTRING_INDEX(mt.classification_path, '-', 1) category_id,mt.master_id from meicloud_bpmp_material.mt_classification mt
AND mt.master_id IN
#{categoryId}
) b on a.master_id=b.category_id

select b.master_id categoryId,a.master_id parentId,a.object_code categoryCode,a.object_name categoryName from meicloud_bpmp_material.mt_classification a inner join ( select SUBSTRING_INDEX(SUBSTRING_INDEX(mt.classification_path, '-', 2), '-', -1) category_id,mt.master_id from meicloud_bpmp_material.mt_classification mt
AND mt.master_id IN
#{categoryId}
) b on a.master_id=b.category_id
